INSERT INTO games (title, platform, released, composers, composers_normalized, notes) VALUES
  ('Jet Set Radio / Jet Grind Radio', 'Dreamcast, Game Boy Advance, PlayStation 3, Xbox 360, PC, PlayStation Vita, iOS, Android, Nintendo Switch, PlayStation 4, Xbox One', '2000-06-29', NULL, NULL, 'Source: NEWER VGM Sound Sources - SEGAAtlus.csv (Section 10 Jet Set Radio). Dual JP/Western title preserved verbatim (JP "Jet Set Radio" / NA "Jet Grind Radio"). CSV says "(Original Music by: See note)" — composers listed inline include B.B. Rights, Billy Brown, F-Fields. The Hideki Naganuma soundtrack borrowed heavily from sample CDs; ~16 cross-media samples identified, plus 179 total identified manufacturer rows + 32 stuff_to_find.'),
  ('Jet Set Radio E3 Prototype',     'Dreamcast',                                                       '2000-04-28', NULL, NULL, 'Source: NEWER VGM Sound Sources - SEGAAtlus.csv (Section 10 Jet Set Radio). E3 demo build shown April 2000, distinct from the June 2000 release. Notable extras: Beastie Boys "(You Gotta) Fight For Your Right (To Party!)" and fIREHOSE "Windmilling" samples in the "Fuzita Blender" placeholder track. Synths KORG MS-20 and Roland System-100M seen on cover of the "Holiday Plug-In!" promo CD.');

